-- D16 L3: 针对 A001 和 A008，分别计算两区面积直接相加、联合覆盖去重面积和重叠面积（平方米），不要将三者混淆。联合覆盖与直接相加应复用同一份区域查询结果。
-- 独立只读基准；EPSG:3857、quad_segs=8；不调用工具或执行器。
-- 直接相加允许重叠重复；union 重叠只计一次；overlap 只取交集。
WITH selected AS (SELECT geom FROM gis_lab.construction_areas WHERE code IN ('A001','A008')), merged AS (SELECT ST_UnaryUnion(ST_Collect(geom)) AS geom FROM selected), overlap AS (SELECT ST_Intersection(a.geom,b.geom) AS geom FROM gis_lab.construction_areas a CROSS JOIN gis_lab.construction_areas b WHERE a.code='A001' AND b.code='A008') SELECT jsonb_build_object('summed_area',(SELECT jsonb_build_object('value',sum(ST_Area(geom)),'unit','square_meter','measure','area','measure_srid',3857,'feature_count',count(*)) FROM selected),'union_area',(SELECT jsonb_build_object('value',ST_Area(geom),'unit','square_meter','measure','area','measure_srid',3857,'is_empty',ST_IsEmpty(geom)) FROM merged),'overlap_area',(SELECT jsonb_build_object('value',ST_Area(geom),'unit','square_meter','measure','area','measure_srid',3857,'is_empty',ST_IsEmpty(geom)) FROM overlap)) AS answer;
